"""Lawvere fixed-point search over finite sets (self-contained)."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Callable, Optional


def all_functions(dom: List[int], cod: List[int]) -> List[Dict[int, int]]:
    return [dict(zip(dom, v)) for v in product(cod, repeat=len(dom))]


def lawvere(phi: Dict[int, Dict[int, int]], dom: List[int],
            g: Callable[[int], int]) -> Optional[int]:
    target = {a: g(phi[a][a]) for a in dom}
    for a0 in dom:
        if phi[a0] == target:
            b = phi[a0][a0]
            assert g(b) == b
            return b
    return None


if __name__ == "__main__":
    # A must be large enough to code all functions A->B for a fixed point of every g.
    B = [0, 1]
    for size in range(1, 6):
        A = list(range(size))
        needed = len(B) ** len(A)
        print(f"|A|={size}: functions A->B = {needed}; "
              f"point-surjective possible = {size >= needed}")

"""Consistent, non-vacuous Gödel provability system (two-sentence model)."""
from __future__ import annotations
from typing import Tuple


class ProvabilitySystem:
    def __init__(self) -> None:
        self.sentences: Tuple[bool, bool] = (False, True)
        self.G: bool = True

    def provable(self, s: bool) -> bool:
        return False

    def holds(self, s: bool) -> bool:
        return s is True

    def neg(self, s: bool) -> bool:
        return not s

    def sound(self) -> bool:
        return all((not self.provable(s)) or self.holds(s) for s in self.sentences)

    def fixed_point(self) -> bool:
        return self.holds(self.G) == (not self.provable(self.G))

    def first_incompleteness(self) -> Tuple[bool, bool]:
        return self.holds(self.G), not self.provable(self.G)

    def undecidable(self) -> Tuple[bool, bool]:
        return not self.provable(self.G), not self.provable(self.neg(self.G))


if __name__ == "__main__":
    s = ProvabilitySystem()
    print("sound:", s.sound(), "| diagonal fixed point:", s.fixed_point())
    print("G true & unprovable:", s.first_incompleteness())
    print("G undecidable:", s.undecidable())

