            b = phi[a0][a0]
            assert g(b) == b
            return b
    return None

from typing import Callable, FrozenSet, List
Theory = FrozenSet[int]

def lfp(f: Callable[[Theory], Theory]) -> Theory:
    x: Theory = frozenset()
    while (nx := f(x)) != x:
        x = nx
    return x

def gfp(f: Callable[[Theory], Theory], universe: List[int]) -> Theory:
    x: Theory = frozenset(universe)
    while (nx := f(x)) != x:
        x = nx
    return x

