from typing import Callable, List, Optional, Tuple

def find_model(n: int,
               phi: List[Callable[[Tuple[bool, ...]], bool]]
               ) -> Optional[Tuple[bool, ...]]:
    for a in product((False, True), repeat=n):
        if all(a[i] == phi[i](a) for i in range(n)):
